//! Scenario tests: each test drives the generated machines through one scenario of the
//! specification, with the expectations Exegra computed for it.

use std::collections::BTreeMap;

use serde::Serialize;
use serde_json::{json, Value};
use strata_runtime::{Machine, Time, TimerCommand};

use strata_spec_compiler_machines_fixture::machines::lease::Lease;

/// What Exegra computed for one delivery to one machine.
enum Expect {
    /// A transition fired.
    Fired {
        /// The state after.
        to: &'static str,
        /// The variables after.
        vars: Value,
        /// The emitted events: receiver, delivery and event.
        emits: Vec<(&'static str, &'static str, Value)>,
        /// The timers set: name, delay in milliseconds and event.
        timers: Vec<(&'static str, i64, Value)>,
        /// The timers pending after, by name.
        pending: &'static [&'static str],
    },
    /// No transition fired: nothing changes and nothing is asked of the runtime.
    Ignored {
        /// The timers pending after, by name.
        pending: &'static [&'static str],
    },
}

/// One machine instance, with the timers the runtime host would keep for it.
struct Run<M: Machine> {
    state: M::State,
    vars: M::Vars,
    /// Pending timers: name to the time they are due and the event they fire.
    timers: BTreeMap<String, (i64, Value)>,
}

fn to_json<T: Serialize>(value: &T) -> Value {
    serde_json::to_value(value).expect("serialisable")
}

impl<M: Machine> Run<M>
where
    M::State: Serialize,
    M::Vars: Serialize,
{
    /// The machine in its initial state, checked against Exegra's initial configuration.
    fn new(key: &str, state: &str, vars: Value) -> Self {
        let key: M::Key = serde_json::from_value(Value::String(key.to_string()))
            .expect("the instance key is the behavior id");
        let (initial_state, initial_vars) = M::initial(&key);
        assert_eq!(
            to_json(&initial_state),
            Value::String(state.to_string()),
            "initial state"
        );
        assert_eq!(to_json(&initial_vars), vars, "initial variables");
        Run {
            state: initial_state,
            vars: initial_vars,
            timers: BTreeMap::new(),
        }
    }

    /// One step of the machine at `now`, then the checks. `timer` names the timer whose firing
    /// delivers `event`: it must be pending, due now, with this event.
    fn deliver(&mut self, at: &str, now: i64, timer: Option<&str>, event: Value, expect: Expect) {
        if let Some(name) = timer {
            let (due, scheduled) = self
                .timers
                .remove(name)
                .unwrap_or_else(|| panic!("{at}: timer {name} is not pending"));
            assert_eq!(due, now, "{at}: when timer {name} is due");
            assert_eq!(scheduled, event, "{at}: the event of timer {name}");
        }
        let event: M::Event = serde_json::from_value(event)
            .unwrap_or_else(|e| panic!("{at}: not an event of the machine: {e}"));
        let outcome = M::step(&self.state, &self.vars, &event, Time(now))
            .unwrap_or_else(|e| panic!("{at}: the step refused: {e}"));
        let mut set = Vec::new();
        for command in &outcome.timers {
            match command {
                TimerCommand::Set { name, after, event } => {
                    let after = i64::try_from(after.as_millis()).expect("a delay in range");
                    set.push((name.as_str(), after, to_json(event)));
                    self.timers
                        .insert(name.clone(), (now + after, to_json(event)));
                }
                TimerCommand::Cancel { name } => {
                    self.timers.remove(name);
                }
            }
        }
        let pending: Vec<&str> = self.timers.keys().map(String::as_str).collect();
        match expect {
            Expect::Fired {
                to,
                vars,
                emits,
                timers,
                pending: expected,
            } => {
                assert_eq!(
                    to_json(&outcome.state),
                    Value::String(to.to_string()),
                    "{at}: state"
                );
                assert_eq!(to_json(&outcome.vars), vars, "{at}: variables");
                let emitted: Vec<(&str, &str, Value)> = outcome
                    .emits
                    .iter()
                    .map(|e| (e.receiver.as_str(), e.delivery.name(), to_json(&e.event)))
                    .collect();
                assert_eq!(emitted, emits, "{at}: emitted events");
                assert_eq!(set, timers, "{at}: timers set");
                assert_eq!(pending, expected, "{at}: timers pending");
            }
            Expect::Ignored { pending: expected } => {
                assert_eq!(
                    to_json(&outcome.state),
                    to_json(&self.state),
                    "{at}: ignored, but the state changed"
                );
                assert_eq!(
                    to_json(&outcome.vars),
                    to_json(&self.vars),
                    "{at}: ignored, but the variables changed"
                );
                assert!(outcome.emits.is_empty(), "{at}: ignored, but emitted");
                assert!(set.is_empty(), "{at}: ignored, but set timers");
                assert_eq!(pending, expected, "{at}: timers pending");
            }
        }
        self.state = outcome.state;
        self.vars = outcome.vars;
    }
}

/// Scenario `lease-run`: Lease run
#[test]
fn scenario_lease_run() {
    let mut run_lease = Run::<Lease>::new(
        "lease",
        "idle",
        json!({"accepted":0,"granted":0,"holder":"","token":0}),
    );

    // Step 0, t=0: lease-requested
    run_lease.deliver(
        "step 0 (t=0, lease-requested)",
        0,
        None,
        json!({"event":"lease-requested","payload":{"holder":"w1"}}),
        Expect::Fired {
            to: "granted",
            vars: json!({"accepted":0,"granted":0,"holder":"w1","token":1}),
            emits: vec![(
                "worker",
                "at-least-once",
                json!({"event":"lease-granted","payload":{"holder":"w1","token":1}}),
            )],
            timers: vec![(
                "expiry",
                30,
                json!({"event":"lease-expired","payload":{"token":1}}),
            )],
            pending: &["expiry"],
        },
    );

    // Step 1, t=0: lease-granted

    // Step 2, t=10: lease-result
    run_lease.deliver(
        "step 2 (t=10, lease-result)",
        10,
        None,
        json!({"event":"lease-result","payload":{"token":7,"value":"forged"}}),
        Expect::Fired {
            to: "granted",
            vars: json!({"accepted":0,"granted":0,"holder":"w1","token":1}),
            emits: vec![(
                "worker",
                "at-most-once",
                json!({"event":"result-stale","payload":{"token":7}}),
            )],
            timers: vec![],
            pending: &["expiry"],
        },
    );

    // Step 3, t=10: result-stale

    // Step 4, t=30: lease-expired
    run_lease.deliver(
        "step 4 (t=30, lease-expired)",
        30,
        Some("expiry"),
        json!({"event":"lease-expired","payload":{"token":1}}),
        Expect::Fired {
            to: "granted",
            vars: json!({"accepted":0,"granted":30,"holder":"w1","token":2}),
            emits: vec![(
                "worker",
                "at-least-once",
                json!({"event":"lease-granted","payload":{"holder":"w1","token":2}}),
            )],
            timers: vec![(
                "expiry",
                30,
                json!({"event":"lease-expired","payload":{"token":2}}),
            )],
            pending: &["expiry"],
        },
    );

    // Step 5, t=30: lease-granted

    // Step 6, t=40: lease-result
    run_lease.deliver(
        "step 6 (t=40, lease-result)",
        40,
        None,
        json!({"event":"lease-result","payload":{"token":1,"value":"late"}}),
        Expect::Fired {
            to: "granted",
            vars: json!({"accepted":0,"granted":30,"holder":"w1","token":2}),
            emits: vec![(
                "worker",
                "at-most-once",
                json!({"event":"result-stale","payload":{"token":1}}),
            )],
            timers: vec![],
            pending: &["expiry"],
        },
    );

    // Step 7, t=40: result-stale

    // Step 8, t=45: lease-result
    run_lease.deliver(
        "step 8 (t=45, lease-result)",
        45,
        None,
        json!({"event":"lease-result","payload":{"token":2,"value":"done"}}),
        Expect::Fired {
            to: "idle",
            vars: json!({"accepted":1,"granted":30,"holder":"w1","token":2}),
            emits: vec![(
                "ledger",
                "at-least-once",
                json!({"event":"result-accepted","payload":{"token":2,"value":"done"}}),
            )],
            timers: vec![],
            pending: &[],
        },
    );

    // Step 9, t=45: result-accepted

    // Step 10, t=50: lease-requested
    run_lease.deliver(
        "step 10 (t=50, lease-requested)",
        50,
        None,
        json!({"event":"lease-requested","payload":{"holder":"w2"}}),
        Expect::Fired {
            to: "granted",
            vars: json!({"accepted":1,"granted":50,"holder":"w2","token":3}),
            emits: vec![(
                "worker",
                "at-least-once",
                json!({"event":"lease-granted","payload":{"holder":"w2","token":3}}),
            )],
            timers: vec![(
                "expiry",
                30,
                json!({"event":"lease-expired","payload":{"token":3}}),
            )],
            pending: &["expiry"],
        },
    );

    // Step 11, t=50: lease-granted

    // Step 12, t=55: lease-requested
    run_lease.deliver(
        "step 12 (t=55, lease-requested)",
        55,
        None,
        json!({"event":"lease-requested","payload":{"holder":"w3"}}),
        Expect::Ignored {
            pending: &["expiry"],
        },
    );

    // Step 13, t=80: lease-expired
    run_lease.deliver(
        "step 13 (t=80, lease-expired)",
        80,
        Some("expiry"),
        json!({"event":"lease-expired","payload":{"token":3}}),
        Expect::Fired {
            to: "granted",
            vars: json!({"accepted":1,"granted":80,"holder":"w2","token":4}),
            emits: vec![(
                "worker",
                "at-least-once",
                json!({"event":"lease-granted","payload":{"holder":"w2","token":4}}),
            )],
            timers: vec![(
                "expiry",
                30,
                json!({"event":"lease-expired","payload":{"token":4}}),
            )],
            pending: &["expiry"],
        },
    );

    // Step 14, t=80: lease-granted

    // Step 15, t=100: lease-result
    run_lease.deliver(
        "step 15 (t=100, lease-result)",
        100,
        None,
        json!({"event":"lease-result","payload":{"token":4,"value":"done"}}),
        Expect::Fired {
            to: "idle",
            vars: json!({"accepted":2,"granted":80,"holder":"w2","token":4}),
            emits: vec![(
                "ledger",
                "at-least-once",
                json!({"event":"result-accepted","payload":{"token":4,"value":"done"}}),
            )],
            timers: vec![],
            pending: &[],
        },
    );

    // Step 16, t=100: result-accepted
}
